window.MOTIF_CATALOG_CHUNKS[66]={"cards":[{"id":"MEJE-KW-006715","row_version":1,"title":"치명적인 기체","original":"Deadly Gas","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"눈에 보이지 않는 기체가 공간을 위협적으로 바꾸는 소재다. 작품에서는 위험을 알아보게 하려고 실제와 다르게 색이나 형태를 부여하기도 한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006715/index.html"},{"id":"MEJE-KW-006716","row_version":1,"title":"죽음을 부르는 시선","original":"Deadly Gaze","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"어떤 존재와 눈이 마주치거나 그 시선을 받으면 치명적인 초자연적 효과가 발생한다. 평범한 눈맞춤이 위험한 접촉으로 바뀐다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006716/index.html"},{"id":"MEJE-KW-006717","row_version":2,"title":"살인을 요구하는 졸업 시험","original":"Deadly Graduation","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"훈련의 마지막 관문에서 동료나 가까운 이를 해치라는 명령을 받는다. 능력 평가를 가장해 충성심과 인간성을 시험한다. 극단적인 훈련 시험은 치명적인 훈련장을 배경으로 삼을 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006717/index.html"},{"id":"MEJE-KW-006718","row_version":2,"title":"목숨을 앗는 신고식","original":"Deadly Hazing","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"새 구성원을 받아들이는 의식이 위험한 가혹행위로 번져 죽음에 이른다. 공동체의 결속이라는 명분 뒤에 숨은 폭력을 드러낸다. 신입에게 요구되는 통과 의식이 생명을 위협한다는 점에서 살인을 요구하는 졸업 시험과 맞닿는다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-006718/index.html"},{"id":"MEJE-KW-006719","row_version":1,"title":"위험한 포옹","original":"Deadly Hug","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"친밀함과 안심을 뜻하는 포옹이 상대를 공격하는 순간으로 뒤집힌다. 관계에 대한 신뢰를 배신하는 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006719/index.html"},{"id":"MEJE-KW-006720","row_version":1,"title":"갑자기 덮치는 느린 괴물","original":"Deadly Lunge","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"느리게 움직이던 괴물이 가까워지자 돌연 빠르게 달려든다. 관객이 익힌 움직임의 규칙을 깨며 놀라움을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006720/index.html"},{"id":"MEJE-KW-006721","row_version":1,"title":"죽음을 예고하는 코피","original":"Deadly Nosebleed","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 코피를 보이지 않는 심각한 손상이나 죽음의 징후처럼 사용하는 영상 관습이다. 실제 의학적 예후를 뜻하기보다 화면 속 불길한 신호다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006721/index.html"},{"id":"MEJE-KW-006722","row_version":2,"title":"치명적인 장난","original":"Deadly Prank","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가볍게 시작한 장난이 심각한 사고나 죽음으로 이어진다. 의도와 결과 사이의 큰 간격이 죄책감이나 갈등을 만든다. 사소한 행동이 돌이킬 수 없는 결과로 이어지는 예로 넘어지며 맞는 갑작스러운 죽음을 들 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006722/index.html"},{"id":"MEJE-KW-006723","row_version":1,"title":"살상 도구가 된 원격 조종 장난감","original":"Deadly Remote Control Toy","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"가해자가 원격 조종 장난감을 살상 도구로 바꾸어 등장시키는 설정. 놀이 물건에 기대한 무해함이 뒤집힌다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006723/index.html"},{"id":"MEJE-KW-006724","row_version":1,"title":"위험한 종소리와 종","original":"Deadly Ringer","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"종이나 종소리가 불길한 신호를 넘어 직접적인 위해의 원인이 되는 장면이다. 의식과 알림의 상징을 위험으로 바꾼다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006724/index.html"},{"id":"MEJE-KW-006725","row_version":1,"title":"죽음의 자동차 여행","original":"Deadly Road Trip","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"낯선 지역을 자유롭게 달리려던 자동차 여행이 고립과 위협의 여정으로 변한다. 이동의 즐거움이 탈출하기 어려운 상황으로 뒤집힌다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006725/index.html"},{"id":"MEJE-KW-006726","row_version":1,"title":"치명적인 회전 팬","original":"Deadly Rotary Fan","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"선풍기나 환풍기의 회전 날개가 작품 안에서 지나치게 위험한 장치처럼 묘사된다. 일상 물건의 위험을 극적으로 부풀리는 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006726/index.html"},{"id":"MEJE-KW-006727","row_version":1,"title":"사소해 보이는 치명상","original":"Deadly Scratch","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"처음에는 가볍게 여겨진 상처가 뒤늦게 치명적인 결과로 이어진다. 눈에 보이는 손상의 크기와 실제 서사적 위험 사이에 차이를 둔다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006727/index.html"},{"id":"MEJE-KW-006728","row_version":2,"title":"위험한 대련","original":"Deadly Sparring","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"연습이나 친선 경기로 시작한 대련이 격해져 심각한 부상이나 죽음의 위험을 낳는다. 통제된 승부라는 믿음이 무너진다. 대련이 벌어지는 공간 자체가 위험하게 설계되었다면 치명적인 훈련장도 함께 나타난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006728/index.html"},{"id":"MEJE-KW-006729","row_version":1,"title":"치명적인 훈련장","original":"Deadly Training Area","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"인물을 단련하기 위해 마련한 공간이 실제 생존을 위협할 만큼 혹독하다. 성장의 장치인 훈련 환경이 갈등의 무대가 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006729/index.html"},{"id":"MEJE-KW-006730","row_version":2,"title":"목숨을 갉아먹는 강화","original":"Deadly Upgrade","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"힘을 크게 높여 주는 강화가 대가로 사용자의 몸이나 생명을 소모한다. 즉각적인 우위와 장기적인 파멸을 맞바꾼다. 초월적인 힘을 얻거나 잃는 일이 모두 치명적일 수 있으며, 반대 방향의 전개는 능력 상실이 부른 죽음이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006730/index.html"},{"id":"MEJE-KW-006731","row_version":1,"title":"닿기만 해도 죽는 게임 벽","original":"Deadly Walls","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"강한 기체나 캐릭터라도 스테이지의 벽에 닿는 순간 즉시 실패하는 게임 규칙이다. 세계관상 강함보다 화면 경계의 규칙이 우선한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006731/index.html"},{"id":"MEJE-KW-006732","row_version":1,"title":"죽은 운전자의 경적","original":"Dead Man Honking","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"의식을 잃거나 죽은 운전자가 경적을 누른 채 쓰러져 긴 소리가 이어진다. 소리가 사건의 결과를 먼저 알리거나 장면의 여운을 남긴다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006732/index.html"},{"id":"MEJE-KW-006733","row_version":2,"title":"상자 속 시신","original":"Dead Man's Chest","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"누군가의 죽음을 숨기려는 인물이 시신을 상자나 가구 속에 감추면서 긴장이 이어진다. 들킬 가능성이 장면의 중심이 된다. 죽은 사람이 살아 있는 것처럼 보이게 만든다는 점에서 죽은 사람으로 신분 위장과 연결될 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006733/index.html"},{"id":"MEJE-KW-006734","row_version":1,"title":"죽은 자의 포커 패","original":"Dead Man's Hand","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"검은 에이스와 검은 8 한 쌍을 죽음과 불운의 징조로 여기는 카드 상징이다. 와일드 빌 히콕의 마지막 패였다는 이야기와 연결되지만 실제 패의 구성은 확실하지 않다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006734/index.html"},{"id":"MEJE-KW-006735","row_version":1,"title":"사망 시 작동하는 대비책","original":"Dead Man's Switch","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"설정자가 죽거나 정해진 신호를 보내지 못하면 미리 준비한 조치가 시작된다. 부재 자체를 새로운 사건의 발단으로 만든다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006735/index.html"},{"id":"MEJE-KW-006736","row_version":1,"title":"죽어 가는 손가락의 발사","original":"Dead Man's Trigger Finger","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"무기를 쥔 인물이 쓰러지는 순간 뜻밖의 발사가 일어나는 장면이다. 이미 끝난 듯한 충돌 뒤에 마지막 위험을 남긴다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006736/index.html"},{"id":"MEJE-KW-006737","row_version":1,"title":"파멸이 예정된 사람","original":"Dead Man Walking","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"주변 사람이나 관객이 곧 죽음 또는 회복하기 어려운 몰락을 맞으리라 여기는 인물이다. 아직 살아 있는 현재와 피할 수 없어 보이는 미래의 간극이 긴장을 만든다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-006737/index.html"},{"id":"MEJE-KW-006738","row_version":2,"title":"죽은 사람이 남긴 글","original":"Dead Man Writing","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"사망한 인물이 남긴 편지나 기록이 뒤늦게 살아 있는 사람에게 전달된다. 고백, 단서, 사과가 부재한 사람의 목소리를 이어 간다. 죽기 전에 직접 말하지 못한 비밀을 남긴다는 점에서 임종 직전의 고백과 짝을 이룬다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006738/index.html"},{"id":"MEJE-KW-006739","row_version":1,"title":"무표정하게 문 닫기","original":"Deadpan Door Shut","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"문을 열어 충격적인 광경을 본 인물이 표정을 바꾸지 않고 다시 문을 닫는다. 과장된 상황과 절제된 반응의 차이로 웃음이나 불안을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006739/index.html"},{"id":"MEJE-KW-006740","row_version":1,"title":"무표정한 독설가","original":"Deadpan Snarker","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"심각하거나 황당한 상황에서도 건조한 표정과 말투로 빈정거리는 인물 유형이다. 날카로운 관찰을 짧은 농담처럼 던진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006740/index.html"},{"id":"MEJE-KW-006741","row_version":2,"title":"죽은 옛 동료","original":"Dead Partner","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 가까이 일하던 동료를 잃은 경험 때문에 새 동료를 거부하거나 복수에 집착한다. 현재 관계를 과거의 상실이 지배한다. 가까운 동료의 죽음이 남은 인물의 행동을 바꾼다는 점에서 죽은 조력자와 이어진다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006741/index.html"},{"id":"MEJE-KW-006742","row_version":2,"title":"죽은 사람과의 대화","original":"Dead Person Conversation","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"산 사람이 죽은 인물과 영혼, 환영, 기억 등의 형태로 대화를 나눈다. 죽음으로 끝난 관계를 말의 교환으로 잠시 다시 연다. 죽은 인물이 이후의 이야기에도 주체로 남는 설정이라면 시작부터 죽은 인물과 연결된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006742/index.html"},{"id":"MEJE-KW-006743","row_version":1,"title":"죽은 사람으로 신분 위장","original":"Dead Person Impersonation","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 이미 죽은 사람의 이름과 정체성을 빌려 다른 사람을 속인다. 죽은 이가 더는 직접 반박할 수 없다는 점이 전개의 조건이 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006743/index.html"},{"id":"MEJE-KW-006744","row_version":1,"title":"죽은 반려동물 대신 구한 닮은 동물","original":"Dead Pet Sketch","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"맡아 돌보던 반려동물이 죽거나 사라지자 관리자가 닮은 동물로 바꿔 놓고 사실을 숨긴다. 주인이 차이를 알아차릴지 모른다는 긴장이 이어진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006744/index.html"},{"id":"MEJE-KW-006745","row_version":2,"title":"농담 아닌 악당","original":"Dead Serious","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"위협이 가벼워 보이던 악당이 중요한 인물을 해치며 자신의 위험성을 입증한다. 작품의 분위기를 한층 무겁게 바꾸는 사건이다. 악당의 위협을 확실히 알리려고 죽은 조력자가 쓰일 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006745/index.html"},{"id":"MEJE-KW-006746","row_version":1,"title":"죽은 조력자","original":"Dead Sidekick","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"주인공과 가까웠던 조력자가 죽으며 주인공의 목표와 태도가 크게 달라진다. 관계의 상실이 복수나 결심의 계기가 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006746/index.html"},{"id":"MEJE-KW-006747","row_version":1,"title":"식어 버린 연인 관계","original":"Dead Sparks","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한때 뜨거웠던 연인 사이의 애정과 설렘이 사라져 관계가 관성처럼 유지된다. 갈등이 없어 보여도 정서적 거리가 벌어진 상태다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006747/index.html"},{"id":"MEJE-KW-006748","row_version":2,"title":"초반에 퇴장하는 유명 배우","original":"Dead Star Walking","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"잘 알려진 배우가 비중 큰 인물처럼 등장하지만 작품 초반에 죽거나 퇴장한다. 배우의 인지도에서 생긴 관객의 예상을 흔든다. 배우의 존재 자체가 관객에게 주는 메타적 정보라는 점에서 제작진의 사망 카메오와 비교할 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006748/index.html"},{"id":"MEJE-KW-006749","row_version":1,"title":"시작부터 죽은 인물","original":"Dead to Begin With","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이야기가 시작될 때 이미 죽어 있는 인물이 주인공이나 주요 시점 인물로 등장한다. 사후 세계나 유령의 삶이 본편의 출발점이 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006749/index.html"},{"id":"MEJE-KW-006750","row_version":1,"title":"리모컨 배터리 방전 소동","original":"Dead TV Remote Gag","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"텔레비전 리모컨이 작동하지 않는 사소한 일을 인물이 큰 재난처럼 받아들인다. 편의에 익숙해진 태도를 과장해 웃음을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006750/index.html"},{"id":"MEJE-KW-006751","row_version":1,"title":"존재하지 않았던 클리셰의 종말","original":"Dead Unicorn Trope","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"널리 쓰인 적도 없는 표현을 진부한 클리셰로 취급하며 풍자하는 현상이다. 작품 속 실상보다 그 표현에 대한 통념이 먼저 퍼진다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006751/index.html"},{"id":"MEJE-KW-006752","row_version":1,"title":"큰 몸집의 좀비","original":"Dead Weight","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"몸집이 큰 좀비를 더 강하고 둔중하거나 불쾌한 괴물 유형처럼 묘사하는 관습이다. 체형을 혐오의 표지로 단정하는 표현은 편견을 강화할 수 있다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006752/index.html"},{"id":"MEJE-KW-006753","row_version":1,"title":"자신의 작품을 감각하지 못하는 창작자","original":"Deaf Composer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"창작자가 감각의 차이나 장애 때문에 자신이 만드는 작품을 일반적인 방식으로 경험하지 못하는 인물 유형이다. 작품은 대체 감각, 협업, 장벽을 넘어서는 창작 방식을 탐색할 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006753/index.html"},{"id":"MEJE-KW-006754","row_version":2,"title":"죽은 뒤 젊어진 모습","original":"De-aged in Death","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"죽은 인물이 영혼이나 사후의 모습으로 나타날 때 생전의 젊은 시절 외형을 취한다. 나이 든 몸과 영원한 자아를 분리해 보여 준다. 사후의 모습을 볼 수 있어도 그 경험을 회상하지 못한다면 사후 기억 상실이 된다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006754/index.html"},{"id":"MEJE-KW-006755","row_version":2,"title":"악마와의 거래","original":"Deal with the Devil","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물이 소원이나 힘을 얻는 대가로 악마 또는 이에 준하는 존재에게 중요한 것을 넘겨주기로 약속한다. 당장의 이익과 나중의 대가가 갈등의 축이 된다. 거래의 대가가 도덕적 선택을 요구할 때 불명예보다 죽음을 택하는 신념과 충돌할 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006755/index.html"},{"id":"MEJE-KW-006756","row_version":1,"title":"원한 많은 학교장","original":"Dean Bitterman","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"학교나 대학의 책임자가 주인공을 사사건건 괴롭히며 규칙과 권위를 개인적 적대에 사용한다. 교육기관 전체가 인물을 압박하는 공간으로 보이게 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006756/index.html"},{"id":"MEJE-KW-006757","row_version":1,"title":"이별 통보 편지","original":"\"Dear John\" Letter","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"연인에게 직접 말하는 대신 편지로 관계의 끝을 알린다. 글을 읽는 시점에는 보낸 사람이 이미 떠나 있어 응답의 기회가 어긋나기도 한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006757/index.html"},{"id":"MEJE-KW-006758","row_version":1,"title":"비판 독자에게 보내는 공개 반박","original":"Dear Negative Reader","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"창작자가 작품을 비판하는 독자나 팬을 향해 공개적으로 반박하거나 꾸짖는다. 작품 밖 갈등이 다시 창작물이나 공식 발표 속으로 들어온다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006758/index.html"},{"id":"MEJE-KW-006759","row_version":2,"title":"죽음으로 발동하는 초능력","original":"Death Activated Superpower","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물의 능력이 살아 있을 때가 아니라 죽음 이후에 비로소 깨어난다. 죽음의 되돌림 가능성과 사후 세계 규칙에 따라 능력의 의미가 달라진다. 죽음 이후 드러나는 힘이 사망 경위와 맞물리면 죽음의 원인을 닮은 유령 능력의 성격도 띤다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006759/index.html"},{"id":"MEJE-KW-006760","row_version":1,"title":"사후 기억 상실","original":"Death Amnesia","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"죽었다가 돌아온 인물이 죽어 있던 동안이나 사후 세계의 경험을 기억하지 못한다. 사후의 실체를 둘러싼 비밀이나 불확실성을 유지한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006760/index.html"},{"id":"MEJE-KW-006761","row_version":1,"title":"죽음과 젊은 여성의 형상","original":"Death and the Maiden","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"죽음을 의인화한 존재와 젊은 여성을 함께 배치하는 오래된 예술 도상이다. 두 형상의 관계를 통해 필멸성, 유혹, 상실을 표현한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006761/index.html"},{"id":"MEJE-KW-006762","row_version":2,"title":"웃음거리로 그린 죽음","original":"Death as Comedy","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"인물의 죽음을 충격이나 비극보다 우스운 사건으로 연출한다. 반복 출연, 과장된 우연, 주변 인물의 반응 등이 희극적 거리를 만든다. 구조의 상징이 죽음의 원인이 되는 구급차에 의한 죽음은 어두운 희극으로 연출될 수 있다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006762/index.html"},{"id":"MEJE-KW-006763","row_version":2,"title":"게임 규칙이 된 플레이어의 죽음","original":"Death as Game Mechanic","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어 캐릭터의 죽음이 진행 중단을 넘어 새로운 선택지나 변화의 조건이 된다. 실패 경험을 게임 세계의 지속적인 규칙으로 편입한다. 죽음 뒤의 변화가 능력의 발동으로 나타난다면 죽음으로 발동하는 초능력과 만난다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006763/index.html"},{"id":"MEJE-KW-006764","row_version":1,"title":"죽음의 원인을 닮은 유령 능력","original":"Death-Based Ghost Powers","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"유령이 자신이 죽은 경위와 연관된 능력이나 외형을 지닌다. 생전의 마지막 사건이 사후 정체성의 일부로 남는다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006764/index.html"},{"id":"MEJE-KW-006765","row_version":1,"title":"임종 직전의 고백","original":"Deathbed Confession","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"죽음을 앞둔 인물이 그동안 숨겨 온 진실이나 감정을 가까운 사람에게 털어놓는다. 뒤늦은 말 한마디가 남은 이들의 관계를 바꾼다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006765/index.html"},{"id":"MEJE-KW-006766","row_version":2,"title":"임종 직전의 명예 승진","original":"Deathbed Promotion","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"죽어 가는 구성원에게 동료나 지휘관이 마침내 바라던 계급과 칭호를 부여한다. 제도상의 승격보다 공동체의 인정과 작별에 무게가 실린다. 임종의 순간 공동체가 말을 건네는 장면이라는 점에서 임종 직전의 고백과 비교할 수 있다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-006766/index.html"},{"id":"MEJE-KW-006767","row_version":1,"title":"불명예보다 죽음을 택하는 신념","original":"Death Before Dishonor","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 자신의 도덕 기준이나 명예를 어기는 일을 생존보다 더 두려워한다. 극단적인 선택 앞에서 가치관의 경직성과 비극성을 드러낸다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006767/index.html"},{"id":"MEJE-KW-006768","row_version":1,"title":"무서운 이름의 귀여운 존재","original":"Deathbringer the Adorable","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"파멸을 부를 듯한 무시무시한 이름을 가진 존재가 실제로는 작고 무해하거나 귀엽다. 이름이 만든 기대와 실체의 차이로 웃음을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006768/index.html"},{"id":"MEJE-KW-006769","row_version":1,"title":"각색판에서만 죽는 인물","original":"Death by Adaptation","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"원작에서는 살아남은 인물이 각색 작품에서 죽거나 더 이른 시점에 죽는다. 원작 독자의 예상을 바꾸고 새 판본의 갈등을 재편한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006769/index.html"},{"id":"MEJE-KW-006770","row_version":1,"title":"구급차에 의한 죽음","original":"Death by Ambulance","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"구조하러 온 구급차가 되레 다른 인물의 죽음에 연루되는 역설적 사건이다. 구원의 상징이 재난의 원인이 되면서 어두운 웃음이나 충격을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006770/index.html"},{"id":"MEJE-KW-006771","row_version":1,"title":"제작진의 사망 카메오","original":"Death by Cameo","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"감독이나 제작자가 화면에 잠깐 등장해 희생자 역할을 맡는다. 제작자의 얼굴을 알아보는 관객에게 메타적인 농담이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006771/index.html"},{"id":"MEJE-KW-006772","row_version":1,"title":"출산 중 사망하는 어머니","original":"Death by Childbirth","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"이야기에서 어머니가 출산 과정에서 사망해 아이와 가족의 출발점에 상실을 남긴다. 특히 부모 부재를 빠르게 설정하는 장치로 반복되어 온 서사 관습이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006772/index.html"},{"id":"MEJE-KW-006773","row_version":1,"title":"지나친 회춘 끝의 소멸","original":"Death by De-aging","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"젊어지는 힘이 멈추지 않아 인물이 태어나기 전 단계까지 거슬러 올라가거나 존재를 잃는다. 영원한 젊음의 소망을 위험한 역설로 바꾼다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006773/index.html"},{"id":"MEJE-KW-006774","row_version":1,"title":"능력 상실이 부른 죽음","original":"Death by Depower","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"생존에 필요한 능력이 갑자기 사라지거나 위기를 버티던 힘을 잃어 인물이 죽는다. 능력의 제거가 곧 보호막의 제거로 작동한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-006774/index.html"},{"id":"MEJE-KW-006775","row_version":1,"title":"절망으로 쇠약해지는 인물","original":"Death by Despair","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"큰 상실을 겪은 인물이 삶의 의지를 잃고 점차 쇠약해져 죽는 것으로 그려진다. 구체적인 의학적 원인보다 비탄의 서사적 표현에 초점을 둔다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006775/index.html"},{"id":"MEJE-KW-006776","row_version":2,"title":"외모 손상 뒤에 예고되는 죽음","original":"Death by Disfigurement","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"한때 아름답게 묘사된 인물이 외모나 몸의 형태에 변화를 겪으면 뒤이어 죽을 것처럼 복선을 놓는 관습이다. 손상 자체가 사망 원인은 아니며 외모에 대한 편견을 반영할 수 있다. 외형의 변화가 앞으로의 죽음을 암시하는 복선이라는 점에서 회상 뒤에 찾아오는 죽음와 비슷하다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006776/index.html"},{"id":"MEJE-KW-006777","row_version":1,"title":"넘어지며 맞는 갑작스러운 죽음","original":"Death by Falling Over","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 밀리거나 발을 헛디뎌 넘어지는 평범한 움직임 뒤에 뜻밖에 죽는다. 작은 사건과 돌이킬 수 없는 결과의 불균형이 충격을 준다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006777/index.html"},{"id":"MEJE-KW-006778","row_version":1,"title":"회상 뒤에 찾아오는 죽음","original":"Death by Flashback","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"한 인물의 과거를 길게 보여 주고 미해결 이야기를 정리한 직후 그 인물이 죽는다. 배경 설명이 작별의 예고처럼 읽히게 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006778/index.html"},{"id":"MEJE-KW-006779","row_version":2,"title":"장르 지식 때문에 죽는 인물","original":"Death by Genre Savviness","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"이야기 속 장르 관습을 잘 안다고 자부하던 인물이 자신이 설명하던 위험에 희생된다. 지식이 생존을 보장할 것이라는 기대를 비튼다. 장르 지식을 자부한 인물이 그 지식과 얽힌 위험으로 죽으면 아이러니한 방식의 죽음의 효과도 생긴다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006779/index.html"},{"id":"MEJE-KW-006780","row_version":1,"title":"과식으로 인한 죽음","original":"Death by Gluttony","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 지나치게 많은 음식을 먹은 결과 죽는 것으로 그려진다. 희극적 과장이나 도덕적 응징의 장치로 쓰일 수 있으나 식습관과 체형을 단순히 동일시해서는 안 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006780/index.html"},{"id":"MEJE-KW-006781","row_version":1,"title":"아이러니한 방식의 죽음","original":"Death by Irony","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 자신의 행동이나 신념과 정반대되거나 상징적으로 맞물리는 방식으로 죽는다. 결말이 인물의 선택을 되돌아보게 만든다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006781/index.html"},{"id":"MEJE-KW-006782","row_version":2,"title":"위를 올려다본 순간의 죽음","original":"Death by Looking Up","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 머리 위로 드리운 그림자를 알아차리고 올려다보는 순간, 거대한 물체가 떨어져 죽음을 맞는 장면. 위험을 깨닫는 짧은 정적이 장면의 충격이나 희극성을 높인다. 위쪽에서 갑자기 닥치는 위협을 죽음의 순간으로 좁혀 보여 주면 상공에서 닥친 공격의 한 변형이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006782/index.html"},{"id":"MEJE-KW-006783","row_version":1,"title":"재물을 놓지 못해 맞는 죽음","original":"Death by Materialism","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"위험 앞에서도 재산이나 소유물을 포기하지 못한 인물이 그 집착 때문에 목숨을 잃는 전개. 탐욕을 인물의 선택과 결말로 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006783/index.html"},{"id":"MEJE-KW-006784","row_version":1,"title":"위험을 비웃다 맞는 죽음","original":"Death by Mocking","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 상대나 위험을 조롱한 직후 그 대상에게 목숨을 잃는 전개. 자신만만한 말과 즉각적인 결과의 간극이 긴장이나 풍자를 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006784/index.html"},{"id":"MEJE-KW-006785","row_version":1,"title":"뮤직비디오 속 출연자의 죽음","original":"Death by Music Video","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"노래의 뮤직비디오가 자체적인 이야기를 펼치며 가수나 출연자의 죽음을 묘사하는 구성. 음악 공연과 극적 사건이 한 영상 안에서 결합한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006785/index.html"},{"id":"MEJE-KW-006786","row_version":2,"title":"성장담 속 가까운 존재의 죽음","original":"Death by Newbery Medal","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"어린 인물이 친구나 가족, 반려동물의 죽음을 겪으며 상실과 성장을 배워 가는 이야기 관습. 죽음은 주인공의 세계 이해가 달라지는 계기가 된다. 성장담에서 상실을 겪는 주체가 어린아이라면 죽음과 처음 마주한 아이의 경험이 중심이 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006786/index.html"},{"id":"MEJE-KW-006787","row_version":2,"title":"기원담을 만든 죽음","original":"Death by Origin Story","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"주인공과 가까운 존재의 죽음이 과거의 결정적 사건으로 남아 현재의 목표나 정체성을 형성한다. 이 상실은 이후 행동의 오래가는 동기가 된다. 어린 시절 겪은 상실이 인물의 출발점으로 남으면 죽음과 처음 마주한 아이와 이어진다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006787/index.html"},{"id":"MEJE-KW-006788","row_version":1,"title":"현명한 선택에도 피하지 못한 죽음","original":"Death by Pragmatism","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"위험을 경계하고 합리적으로 행동하던 인물까지 죽는 전개. 생존 장르의 익숙한 기대를 깨뜨려 위협의 불가피성을 강조한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006788/index.html"},{"id":"MEJE-KW-006789","row_version":1,"title":"차별적 인물에게 닥친 파국","original":"Death by Racism","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"편견이나 차별을 드러내던 인물이 이야기 속 위협으로 죽음을 맞고, 작품이 이를 그 인물의 도덕적 결말처럼 배치하는 관습. 죽음과 차별 문제를 단순한 응보로 엮는 표현을 살펴볼 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006789/index.html"},{"id":"MEJE-KW-006790","row_version":2,"title":"정체를 알아보고 제거되는 목격자","original":"Death by Recognition","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"주변 인물이 악역의 정체를 알아차리지만 다른 사람에게 알리기 전에 죽는 전개. 밝혀질 뻔한 비밀이 다시 감춰지며 긴장이 이어진다. 위험한 정체를 알아본 탓에 죽는다는 점에서 비밀 정체를 안 뒤 맞는 죽음와 나란히 살펴볼 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006790/index.html"},{"id":"MEJE-KW-006791","row_version":1,"title":"비밀 정체를 안 뒤 맞는 죽음","original":"Death by Secret Identity","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"영웅의 숨겨진 정체를 알게 된 인물이 곧 목숨을 잃어 그 지식을 다른 사람에게 전하지 못하는 전개. 발견의 여파와 비밀 유지가 한 사건에 묶인다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006791/index.html"},{"id":"MEJE-KW-006792","row_version":2,"title":"통신기 너머로 들은 마지막 순간","original":"Death by Transceiver","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"한 인물이 무전이나 통화로 멀리 있는 사람의 마지막 소리를 듣고도 개입하지 못하는 장면. 보이지 않는 사건을 소리와 듣는 이의 반응으로 전달한다. 마지막 소리를 듣는 장면 뒤에는 공식적인 사망 소식 전달이 이어질 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006792/index.html"},{"id":"MEJE-KW-006793","row_version":1,"title":"배신당한 연인의 살해","original":"Death by Woman Scorned","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"연인에게 배신당했다고 느낀 인물이 그 상대를 죽이는 복수 서사. 관계의 상처가 폭력적 결말로 이어지는 작품 속 묘사이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006793/index.html"},{"id":"MEJE-KW-006794","row_version":1,"title":"데스코어","original":"Deathcore","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"데스메탈의 강한 보컬과 연주 감각을 메탈코어의 리듬과 구성에 결합한 익스트림 메탈 장르. 음악 장르를 나타내는 키워드이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006794/index.html"},{"id":"MEJE-KW-006795","row_version":1,"title":"연속 함정 구간","original":"Death Course","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"인물이 목적지에 이르려면 치명적인 함정이 이어지는 통로 또는 구간을 지나야 하는 구성. 연속된 장애물이 이동 자체를 하나의 시련으로 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006795/index.html"},{"id":"MEJE-KW-006796","row_version":1,"title":"메아리치는 마지막 비명","original":"Death Cry Echo","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"죽어 가는 인물의 비명이 여러 차례 울리거나 점차 사라지는 음향 연출. 화면에 남은 사건의 여운을 소리로 늘린다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006796/index.html"},{"id":"MEJE-KW-006797","row_version":1,"title":"죽음을 숭배하는 집단","original":"Death Cult","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"죽음이나 살해를 신앙과 의식의 중심에 두는 허구의 집단. 작품은 이를 집단의 가치관과 위험성을 알리는 설정으로 사용한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-006797/index.html"},{"id":"MEJE-KW-006798","row_version":1,"title":"투척 카드 전투원","original":"Death Dealer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평범한 놀이 도구인 카드를 특별한 전투 수단처럼 사용하는 인물형. 익숙한 물건의 기능을 과장해 독특한 전투 이미지를 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006798/index.html"},{"id":"MEJE-KW-006799","row_version":2,"title":"죽음 앞에서 드러난 감정","original":"Death Equals Emotion","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"평소 감정을 억누르거나 드러내지 않던 인물이 죽음을 앞두고 비로소 마음을 표현하는 전개. 마지막 순간이 숨겨진 내면을 보이게 한다. 마지막 순간에 숨겨 둔 마음을 내보이는 장면은 얼굴을 드러내는 죽어 가며 벗는 가면과 결합할 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006799/index.html"},{"id":"MEJE-KW-006800","row_version":2,"title":"죽음을 앞둔 악역의 참회","original":"Death Equals Redemption","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"자신의 죽음이 가까워졌음을 알게 된 악역이 이전 행동을 돌아보고 태도를 바꾸는 전개. 변화의 동기가 임박한 끝에 있다는 점이 핵심이다. 참회의 진정성을 마지막 감정 표현으로 보이면 죽음 앞에서 드러난 감정과 만난다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006800/index.html"},{"id":"MEJE-KW-006801","row_version":1,"title":"남이 꾸민 죽음 위장","original":"Death Faked for You","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"추적받는 인물을 구하기 위해 다른 사람이 그 인물의 죽음을 거짓으로 꾸미는 전개. 위장된 상실은 추적을 멈추게 하거나 새로운 정체성의 여지를 만든다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006801/index.html"},{"id":"MEJE-KW-006802","row_version":1,"title":"죽음 중심 팬픽","original":"Death Fic","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"팬 창작물이 한 인물의 죽음과 남겨진 사람들의 반응을 중심으로 이야기를 전개하는 유형. 기존 작품의 관계와 감정을 상실이라는 가정에서 다시 살핀다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006802/index.html"},{"id":"MEJE-KW-006803","row_version":1,"title":"비행 중 벌어지는 국가 폭력","original":"Death Flight","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"권력 기관이 비행기를 이용한 살해를 저지르는 역사적 폭력을 이야기 속에 다루는 소재. 비밀스러운 국가 폭력과 책임의 문제를 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006803/index.html"},{"id":"MEJE-KW-006804","row_version":2,"title":"상공에서 닥친 공격","original":"Death from Above","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물의 위쪽 공간에서 갑작스러운 공격이나 물체의 낙하가 일어나는 장면. 시야 밖의 높은 위치가 예기치 않은 위협으로 작동한다. 낙하하는 물체를 인물이 올려다보게 하면 위를 올려다본 순간의 죽음의 장면이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006804/index.html"},{"id":"MEJE-KW-006805","row_version":1,"title":"죽일 듯한 눈빛","original":"Death Glare","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 말없이 차갑고 위협적인 시선을 보내 상대를 압도하는 표정 연기. 실제 초능력보다는 감정과 관계의 긴장을 보여 주는 표현이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006805/index.html"},{"id":"MEJE-KW-006806","row_version":2,"title":"구금 중 사망","original":"Death in Custody","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"체포되거나 구금된 인물이 기관의 관리 아래 있는 동안 죽는 사건. 사망 경위와 관리 책임을 둘러싼 갈등이 뒤따를 수 있다. 사망한 수감자에게 잘못을 떠넘기는 전개라면 고인에게 뒤집어씌운 책임이라는 별도의 계략이 겹친다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006806/index.html"},{"id":"MEJE-KW-006807","row_version":1,"title":"항공기 안의 살인 사건","original":"Death in the Clouds","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"운항 중인 비행기에서 살인이 벌어져 한정된 승객과 승무원이 용의자가 되는 미스터리 구성. 이동 중인 폐쇄 공간이 수사의 조건을 만든다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006807/index.html"},{"id":"MEJE-KW-006808","row_version":1,"title":"무능한 죽음의 의인화","original":"Death Is a Loser","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"죽음을 맡는 초자연적 존재가 허술하거나 쉽게 당하는 인물로 묘사되는 방식. 절대적인 힘이라는 기대를 뒤집어 희극을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006808/index.html"},{"id":"MEJE-KW-006809","row_version":2,"title":"죽음과 처음 마주한 아이","original":"Death Is a Sad Thing","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"어린 인물이 가까운 존재의 죽음을 처음 겪으며 상실과 유한성을 이해하기 시작하는 전개. 아이의 질문과 슬픔이 사건의 중심에 놓인다. 아이의 첫 상실을 성장 이야기의 전환점으로 사용하면 성장담 속 가까운 존재의 죽음이 된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006809/index.html"},{"id":"MEJE-KW-006810","row_version":2,"title":"가벼운 게임 속 사망 대가","original":"Death Is a Slap on the Wrist","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 캐릭터가 죽어도 작은 불이익만 받고 곧 다시 시도할 수 있는 규칙. 사망의 극적 무게보다 반복 플레이의 흐름을 앞세운다. 반복해서 다시 시작할 수 있는 이유를 이야기 속 규칙으로 설명하면 재도전을 설명하는 불사의 설정이 더해진다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006810/index.html"},{"id":"MEJE-KW-006811","row_version":2,"title":"되풀이되는 죽음과 귀환","original":"Death Is Cheap","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"중요 인물이 죽은 듯하다가 자주 돌아오는 서사 관습. 반복될수록 죽음이 가진 최종성과 긴장감이 약해질 수 있다. 반복되는 귀환이 게임 속 정식 규칙이라면 재도전을 설명하는 불사의 설정의 설정으로 풀 수 있다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006811/index.html"},{"id":"MEJE-KW-006812","row_version":1,"title":"과장된 임종 장면","original":"Death Is Dramatic","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"인물의 마지막 순간을 긴 말과 강한 감정, 극적인 무대감으로 표현하는 연출. 사건의 크기를 관객에게 직접 느끼게 한다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006812/index.html"},{"id":"MEJE-KW-006813","row_version":1,"title":"죽음과 함께 사라지는 색","original":"Death Is Gray","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 죽거나 생명력을 잃을 때 몸의 색이 빠져 회색으로 보이는 시각 표현. 변화된 색채가 생명의 소멸을 즉시 알린다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006813/index.html"},{"id":"MEJE-KW-006814","row_version":1,"title":"재도전을 설명하는 불사의 설정","original":"Death Is Not Permanent","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 안에서 캐릭터가 죽은 뒤 다시 시도할 수 있는 이유를 세계의 규칙으로 설명하는 장치. 반복 플레이가 이야기 속 사건과 연결된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006814/index.html"}]}.cards;